import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long[] a = new long[(int) n];
        for (int i = 0; i < a.length; i++) a[i] = Long.parseLong(next());

        final long MOD = 1000000007L;
        int m = (int) n;
        long[] left = new long[m], right = new long[m];
        Deque<Integer> stack = new ArrayDeque<>();
        for (int i = 0; i < m; i++) {
            while (!stack.isEmpty() && a[stack.peek()] > a[i]) stack.pop();
            left[i] = i - (stack.isEmpty() ? -1 : stack.peek());
            stack.push(i);
        }
        stack.clear();
        for (int i = m - 1; i >= 0; i--) {
            while (!stack.isEmpty() && a[stack.peek()] >= a[i]) stack.pop();
            right[i] = (stack.isEmpty() ? m : stack.peek()) - i;
            stack.push(i);
        }
        long total = 0;
        for (int i = 0; i < m; i++) total = (total + a[i] * left[i] % MOD * right[i]) % MOD;
        System.out.println(total);
    }
}
